import unicodedata as u
def w(s):
    n=0
    for c in s:
        if u.category(c) in ('Mn','Me','Cf'): continue
        n += 2 if u.east_asian_width(c) in ('W','F') else 1
    return n
for s in ['abc','日本語','ｱｲｳ','Ａ','○①α','é','é','😀','a‍b','認証(ログイン、セッション、トークン更新)','','\t']:
    print(repr(s), [u.east_asian_width(c) for c in s], w(s))
print(u.unidata_version)
